const input = $input.first().json;
const event = input.event ?? input;

if (
  event.bot_id ||
  event.subtype === 'bot_message' ||
  event.type === 'bot_message'
) {
  return [];
}

const text = String(event.text ?? '').trim();

if (!text) {
  return [];
}

return [{
  json: {
    chatInput: text,
    user: event.user ?? null,
    channel: event.channel ?? null,
    ts: event.ts ?? null,
    originalEvent: event,
  },
}];

const item = $input.item.json;

const channel = item.channel;
const ts = item.ts;

if (!channel || !ts) {
  throw new Error('Missing Slack channel or message timestamp.');
}

return {
  json: {
    ...item,
    eventKey: `slack:${channel}:${ts}`,
    processingStatus: 'new',
  },
};

const input = $input.item.json;
const agentOutput = String(input.output ?? '');

const normalizedOutput = agentOutput
  .replace(/\r/g, '')
  .trim()
  .toLowerCase();

const getField = (label) => {
  const regex = new RegExp(
    `(?:^|\\n)\\s*(?:[-*]\\s*)?${label}\\s*:\\s*(.+)`,
    'i'
  );

  const match = agentOutput.match(regex);
  return match ? match[1].trim() : '';
};

const prospectiveClient =
  getField('Prospective client') ||
  getField('Prospective Client');

const opposingParties =
  getField('Opposing party') ||
  getField('Opposing parties') ||
  getField('Opposing Party');

const findings =
  getField('Findings') ||
  getField('Key findings') ||
  getField('Key Findings');

const nextStep =
  getField('Next step') ||
  getField('Next steps') ||
  getField('Next Steps');

const potentialConflict =
  normalizedOutput.includes('status: potential conflict identified') ||
  normalizedOutput.includes('overall status: potential conflict identified');

return {
  json: {
    ...input,

    status: potentialConflict
      ? 'Potential conflict identified'
      : 'No potential conflict found',

    potentialConflict,

    prospectiveClient,
    opposingParties,
    findings,
    nextStep,

    reviewedAt: new Date().toISOString(),

    // Useful original Slack fields for Google Sheets
    eventKey: input.eventKey ?? '',
    slackUserId: input.user ?? '',
    channelId: input.channel ?? '',
    messageTs: input.ts ?? '',
    requestText: input.chatInput ?? '',
  },
};

const agentOutput = $input.item.json.output ?? '';

return {
  json: {
    output:
`⚠️ *Potential conflict identified*

${agentOutput}

_No conflict has been cleared automatically. Human review is required before engagement._`,
    channel: $('Prepare Authenticated Input').item.json.channel,
    ts: $('Prepare Authenticated Input').item.json.ts,
  },
};

const input = $input.item.json;
const agentOutput = String(input.output ?? '');

return {
  json: {
    output:
`✅ *No potential conflict found in the searched records*

${agentOutput}

_This is a preliminary automated search only. It does not clear the matter; human review is required before engagement._`,
    channel: input.channel,
    ts: input.ts,
  },
};

const original = $('Generate Event Key').item.json;

return {
  json: {
    chatInput: original.chatInput,
    eventKey: original.eventKey,
    user: original.user,
    channel: original.channel,
    ts: original.ts,
    originalEvent: original.originalEvent,
  },
};
